)];\n  if (path) {\n    return html`\n      <svg\n        class=\"brand-icon\"\n        viewBox=\"0 0 24 24\"\n        width=\"20\"\n        height=\"20\"\n        aria-hidden=\"true\"\n        focusable=\"false\"\n      >\n        <path d=${path}></path>\n      </svg>\n    `;\n  }\n  return html`<i class=\"icon\" aria-hidden=\"true\">${name}</i>`;\n}\n", "/**\n * @file LinkList.ts\n * @description The core link list. Each item is a semantic anchor with an\n * optional icon, title and Markdown subtitle, plus correct `target`/`rel`\n * handling for `new_tab` and `nofollow`.\n */\nimport { html, } from \"htm/preact\";\nimport type { LinkItem, } from \"../lib/types.ts\";\nimport { BrandIcon, } from \"./BrandIcon.ts\";\nimport { MarkdownText, } from \"./MarkdownText.ts\";\n\n/** Compose the `rel` attribute from the link's open/nofollow flags. */\nfunction relFor(link: LinkItem,): string | undefined {\n  const rel: string[] = [];\n  if (link.new_tab) rel.push(\"noopener\", \"noreferrer\",);\n  if (link.nofollow) rel.push(\"nofollow\",);\n  return rel.length ? rel.join(\" \",) : undefined;\n}\n\nexport interface LinkRowProps {\n  link: LinkItem;\n}\n\nexport function LinkRow({ link, }: LinkRowProps,) {\n  // `is-` prefixed variants: bare `button`/`featured` would collide with\n  // BeerCSS's own `.button` component styles.\n  const cls = [\n    \"link\",\n    link.button ? \"is-button\" : \"\",\n    link.featured ? \"is-featured\" : \"\",\n  ].filter(Boolean,).join(\" \",);\n\n  return html`\n    <li class=${cls}>\n      <a\n        href=${link.url}\n        target=${link.new_tab ? \"_blank\" : undefined}\n        rel=${relFor(link,)}\n      >\n        ${link.icon\n          ? html`<span class=\"link-icon\"><${BrandIcon} name=${link.icon} /></span>`\n          : null}\n        <span class=\"link-body\">\n          <span class=\"link-title\">${link.title}</span>\n          ${link.subtitle\n            ? html`\n              <span class=\"link-subtitle\">\n                <${MarkdownText} text=${link.subtitle} inline=${true} />\n              </span>\n            `\n            : null}\n        </span>\n        ${link.new_tab\n          ? html`<i class=\"icon chevron\" aria-hidden=\"true\">open_in_new</i>`\n          : null}\n      </a>\n    </li>\n  `;\n}\n\nexport interface LinkListProps {\n  links: LinkItem[];\n}\n\nexport function LinkList({ links, }: LinkListProps,) {\n  return html`\n    <nav class=\"links-nav\" aria-label=\"Links\">\n      <ul class=\"links\">\n        ${links.map((link, i,) => html`<${LinkRow} link=${link} key=${i} />`)}\n      </ul>\n    </nav>\n  `;\n}\n", "/**\n * @file ProfileHeader.ts\n * @description Avatar, name, tagline and (Markdown) bio for the bio header.\n */\nimport { html, } from \"htm/preact\";\nimport type { Profile, } from \"../lib/types.ts\";\nimport { MarkdownText, } from \"./MarkdownText.ts\";\n\nexport interface ProfileHeaderProps {\n  profile: Profile;\n}\n\nexport function ProfileHeader({ profile, }: ProfileHeaderProps,) {\n  return html`\n    <header class=\"profile\">\n      ${profile.avatar\n        ? html`\n          <img\n            class=\"avatar\"\n            src=${profile.avatar}\n            alt=${profile.avatar_alt ?? \"\"}\n            width=\"96\"\n            height=\"96\"\n          />\n        `\n        : null}\n      <h1 class=\"name\">${profile.name}</h1>\n      ${profile.tagline\n        ? html`\n          <p class=\"tagline\">\n            <${MarkdownText} text=${profile.tagline} inline=${true} />\n          </p>\n        `\n        : null}\n      ${profile.bio\n        ? html`\n          <div class=\"bio\">\n            <${MarkdownText} text=${profile.bio} />\n          </div>\n        `\n        : null}\n      ${profile.location\n        ? html`\n          <p class=\"location\">\n            <i class=\"icon\" aria-hidden=\"true\">place</i>${profile.location}\n          </p>\n        `\n        : null}\n    </header>\n  `;\n}\n", "/**\n * @file App.ts\n * @description Root component: composes the profile header, before-sections,\n * the link list, after-sections and the optional footer from the validated\n * config. Reads from the `configSignal` store unless a `config` prop is passed\n * (the latter keeps server-side rendering and tests pure/deterministic).\n */\nimport { html, } from \"htm/preact\";\nimport { configSignal, } from \"./state.ts\";\nimport type { LinklistConfig, } from \"../lib/types.ts\";\nimport { ContentSection, } from \"./ContentSection.ts\";\nimport { Footer, } from \"./Footer.ts\";\nimport { LinkList, } from \"./LinkList.ts\";\nimport { ProfileHeader, } from \"./ProfileHeader.ts\";\n\nexport interface AppProps {\n  config?: LinklistConfig;\n  /** Build timestamp for the footer (defaults to now). */\n  timestamp?: number;\n}\n\nexport function App(props: AppProps = {},) {\n  const config = (props.config ?? configSignal.value) as LinklistConfig | null;\n  if (!config) {\n    return html`<div class=\"empty\">No configuration loaded.</div>`;\n  }\n\n  const sections = config.sections ?? [];\n  const before = sections.filter((s,) => s.placement === \"before\");\n  const after = sections.filter((s,) => s.placement !== \"before\");\n  const mode = config.theme?.mode ?? \"auto\";\n\n  return html`\n    <main\n      class=\"linklist\"\n      data-theme=${config.theme.preset}\n      data-mode=${mode}\n    >\n      <${ProfileHeader} profile=${config.profile} />\n      ${before.map((section, i,) =>\n        html`<${ContentSection} section=${section} key=${`before-${i}`} />`\n      )}\n      <${LinkList} links=${config.links} />\n      ${after.map((section, i,) =>\n        html`<${ContentSection} section=${section} key=${`after-${i}`} />`\n      )}\n      ${config.plugins?.show_last_updated\n        ? html`\n          <${Footer}\n            label=${config.plugins.footer_label}\n            timestamp=${props.timestamp ?? Date.now()}\n          />\n        `\n        : null}\n    </main>\n  `;\n}\n", "/**\n * @file engine.ts\n * @description Plugin contract and orchestration. Plugins run where the host\n * puts them: at build time for the SaaS tier, or in the browser for the static\n * site. Either way they fetch remote data through an **injected** `fetchJson`\n * (never a global) and return plain data that core merges into the config before\n * rendering. Nothing is fetched unless the user opts a plugin in via config, and\n * there is no analytics/tracking — honoring the privacy and performance rules.\n * Because the network and filesystem stay on the caller's side, this module is\n * reusable by the SaaS tier.\n */\nimport type {\n  ContentSection,\n  LinkItem,\n  LinklistConfig,\n} from \"../lib/types.ts\";\n\n/** What a plugin contributes to the page. Both are appended, never replacing. */\nexport interface PluginOutput {\n  /** Extra links added to the link list. */\n  links?: LinkItem[];\n  /** Extra content sections added after the links. */\n  sections?: ContentSection[];\n}\n\n/** Everything a plugin is allowed to touch. Fully injectable for tests. */\nexport interface PluginContext {\n  /** The validated config (read-only source of truth). */\n  config: LinklistConfig;\n  /** Fetch and parse a JSON resource. Provided by the host; mocked in tests. */\n  fetchJson(url: string,): Promise<unknown>;\n  /** Report a non-fatal, human-readable warning. */\n  warn(message: string,): void;\n}\n\n/** A build-time plugin. */\nexport interface LinklistPlugin {\n  /** Unique plugin id, used in logs. */\n  name: string;\n  /** Run the plugin, returning data contributions. */\n  run(ctx: PluginContext,): Promise<PluginOutput>;\n}\n\n/**\n * Run plugins in order, isolating failures: a plugin that throws (for example a\n * rate-limited or offline fetch) only logs a warning and is skipped, so the\n * static build still succeeds.\n *\n * @param plugins - The plugins to run.\n * @param ctx - The injectable plugin context.\n * @returns The collected outputs (empty entries omitted by the caller's merge).\n */\nexport async function runPlugins(\n  plugins: LinklistPlugin[],\n  ctx: PluginContext,\n): Promise<PluginOutput[]> {\n  const outputs: PluginOutput[] = [];\n  for (const plugin of plugins) {\n    try {\n      outputs.push(await plugin.run(ctx,),);\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error,);\n      ctx.warn(`${plugin.name} skipped: ${message}`,);\n    }\n  }\n  return outputs;\n}\n\n/**\n * Merge plugin outputs into a copy of the config (links and sections are\n * appended). The original config is never mutated.\n *\n * @param config - The validated base config.\n * @param outputs - Outputs returned by {@link runPlugins}.\n * @returns A new config with plugin contributions appended.\n */\nexport function mergePluginOutputs(\n  config: LinklistConfig,\n  outputs: PluginOutput[],\n): LinklistConfig {\n  const links = [...config.links,];\n  const sections = [...(config.sections ?? []),];\n  for (const output of outputs) {\n    if (output.links) links.push(...output.links,);\n    if (output.sections) sections.push(...output.sections,);\n  }\n  return { ...config, links, sections, };\n}\n", "/**\n * @file github_repos.ts\n * @description `github-repos` plugin. For each `config.plugins.github_repos`\n * entry it fetches the repo (star count) and its latest release through the\n * injected `ctx.fetchJson` and emits a \"GitHub\" Markdown section. It runs where\n * the host places it — at build time (SaaS) or in the browser — and only fires\n * when the user opts in via config (no default network calls).\n */\nimport type { LinklistPlugin, PluginContext, PluginOutput, } from \"./engine.ts\";\n\ninterface GhRepo {\n  stargazers_count?: number;\n  html_url?: string;\n}\n\ninterface GhRelease {\n  tag_name?: string;\n}\n\n/** Build one Markdown list item for a repo, tolerating a missing latest release. */\nasync function repoLine(ctx: PluginContext, repo: string,): Promise<string> {\n  const info = (await ctx.fetchJson(\n    `https://api.github.com/repos/${repo}`,\n  )) as GhRepo;\n  let meta = `★ ${info.stargazers_count ?? 0}`;\n  try {\n    const release = (await ctx.fetchJson(\n      `https://api.github.com/repos/${repo}/releases/latest`,\n    )) as GhRelease;\n    if (release?.tag_name) meta += ` · ${release.tag_name}`;\n  } catch {\n    // Repos without releases return 404; that is expected, keep just the stars.\n  }\n  const url = info.html_url ?? `https://github.com/${repo}`;\n  return `- [${repo}](${url}) — ${meta}`;\n}\n\nexport const githubReposPlugin: LinklistPlugin = {\n  name: \"github-repos\",\n  async run(ctx: PluginContext,): Promise<PluginOutput> {\n    const repos = ctx.config.plugins?.github_repos ?? [];\n    if (repos.length === 0) return {};\n    const lines: string[] = [];\n    for (const repo of repos) {\n      lines.push(await repoLine(ctx, repo,),);\n    }\n    return {\n      sections: [{\n        title: \"GitHub\",\n        body: lines.join(\"\\n\",),\n        placement: \"after\",\n      },],\n    };\n  },\n};\n", "/**\n * @file mod.ts\n * @description Built-in plugins for `@vanaware/linklist`.\n *\n * Plugins fetch remote data (GitHub stars, latest release) through the injected\n * `fetchJson` and return plain data that core merges into the config before\n * rendering — only when the user opts a plugin in via config. They live in core\n * so the engine and its default plugins ship together; there is no separate\n * plugins package.\n */\nimport type { LinklistPlugin, } from \"./engine.ts\";\nimport { githubReposPlugin, } from \"./github_repos.ts\";\n\nexport { githubReposPlugin, } from \"./github_repos.ts\";\n\n/** Plugins core runs automatically. Extend this list to add more. */\nexport const builtinPlugins: LinklistPlugin[] = [githubReposPlugin,];\n", "/**\n * Extracts duplicated elements and their indices from an array, returning them.\n *\n * Note that given `a === b && b === c`, then `c === a` must be `true` for this to give accu